import { createContext, createElement, useContext, useMemo, useRef } from "react";

const HookFormContext = createContext(null);
HookFormContext.displayName = "HookFormContext";

const HookFormControlContext = createContext(null);
HookFormControlContext.displayName = "HookFormControlContext";

export const useFormContext = () => useContext(HookFormContext);

export const FormProvider = (props) => {
  const { children, ...data } = props;
  return createElement(
    HookFormContext.Provider,
    { value: data },
    createElement(HookFormControlContext.Provider, { value: data.control }, children),
  );
};

export const useForm = (props = {}) => {
  const control = useRef(null);
  if (!control.current) {
    control.current = { _defaultValues: props.defaultValues ?? {}, _names: { mount: new Set() } };
  }
  const methods = useMemo(
    () => ({ control: control.current, getValues: () => control.current._defaultValues }),
    [],
  );
  return methods;
};
